  "sim.egg-incubator.title": "Incubadora de huevos",
  "sim.egg-incubator.desc": "Gestiona la temperatura, la humedad y la rotación de los huevos en una incubadora para maximizar la tasa de eclosión.",
  "sim.dairy-farm.title": "Granja lechera",
  "sim.dairy-farm.desc": "Gestiona una pequeña explotación lechera: horarios de alimentación, ciclos de ordeño y salud del rebaño para maximizar la producción.",
  "sim.poultry-farm.title": "Granja avícola",
  "sim.poultry-farm.desc": "Gestiona una granja avícola comercial: alimentación, salud y objetivos de producción para los lotes de engorde y puesta.",
  "sim.cattle-dairy.title": "Ganado y lechería",
  "sim.cattle-dairy.desc": "Supervisa una ganadería y una unidad lechera, equilibrando la gestión del pasto, la cría y la producción de leche.",
  "sim.sheep-farm.title": "Granja de ovejas",
  "sim.sheep-farm.desc": "Gestiona una granja de ovejas mediante ciclos estacionales: partos, esquila y ventas al mercado.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Actúa como ingeniero de un Centro de Operaciones de Red (NOC): diagnostica y resuelve incidencias de infraestructura en vivo bajo presión.",
  "sim.mobile-repair.title": "Taller móvil de reparación",
  "sim.mobile-repair.desc": "Diagnostica y repara smartphones: reemplazos de pantalla, problemas de batería y fallos en la placa base.",
  "sim.laptop-repair.title": "Taller de reparación de portátiles",
  "sim.laptop-repair.desc": "Soluciona y repara portátiles: fallos de hardware, problemas de BIOS y sustitución de componentes.",
  "sim.perfume-lab.title": "Laboratorio de Perfumes",
  "sim.perfume-lab.desc": "Mezcla aceites esenciales y compuestos aromáticos para crear fragancias distintivas y alcanzar puntos de calidad.",
  "sim.detergent-lab.title": "Laboratorio de detergentes",
  "sim.detergent-lab.desc": "Formula productos de limpieza: equilibra tensioactivos, cargas y pruebas de rendimiento dentro del presupuesto.",
  "sim.skin-care-lab.title": "Laboratorio de cuidado de la piel",
  "sim.skin-care-lab.desc": "Desarrolla y prueba formulaciones cosméticas, cumpliendo normas de seguridad y objetivos de eficacia.",
  "sim.woodworking.title": "Taller de carpintería",
  "sim.woodworking.desc": "Dirige una carpintería personalizada: planifica trabajos, gestiona materiales y entrega muebles a tiempo y dentro del presupuesto.",
  "sim.aluminum-glazing.title": "Aluminio y acristalamiento",
  "sim.aluminum-glazing.desc": "Gestiona un negocio de fabricación de aluminio e instalación de vidrio desde la cotización hasta la finalización en obra.",
  "sim.global-kitchen.title": "Cocina global",
  "sim.global-kitchen.desc": "Lidera una cocina de restaurante: gestiona menús, personal, costes y satisfacción del cliente en distintos turnos de servicio.",
  "sim.chocolate-factory.title": "Fábrica de chocolate",
  "sim.chocolate-factory.desc": "Opera una fábrica de confitería: aprovisiona cacao, programa la producción y realiza control de calidad.",
  "sim.solar-energy.title": "Central de energía solar",
  "sim.solar-energy.desc": "Diseña y opera una instalación solar: dimensiona paneles, gestiona la exportación a la red y supervisa el ROI.",
  "sim.hvac-systems.title": "Sistemas de HVAC",
  "sim.hvac-systems.desc": "Instala y mantiene sistemas de calefacción, ventilación y aire acondicionado para edificios comerciales.",
  "sim.logistics-supply.title": "Logística y cadena de suministro",
  "sim.logistics-supply.desc": "Optimiza las operaciones del almacén, la planificación de rutas de la flota y las relaciones con proveedores para cumplir KPIs de entrega.",
  "sim.barber-salon.title": "Salón de barbería",
  "sim.barber-salon.desc": "Gestiona una barbería: citas, horarios del personal, precios y estrategias de retención de clientes.",
  "sim.board-surgeon.title": "Cirujano de guardia",
  "sim.board-surgeon.desc": "Toma decisiones quirúrgicas de alto riesgo en un quirófano simulado: gestión del tiempo y seguridad del paciente.",
  "sim.english-journey.title": "Viaje en inglés",
  "sim.english-journey.desc": "Guía a los alumnos a través de un programa estructurado de inglés, adaptándolo a diferentes niveles de habilidad.",
  "sim.music-training.title": "Estudio de formación musical",
  "sim.music-training.desc": "Dirige una escuela de música: programa clases, gestiona instrumentos y hace seguimiento del progreso de los estudiantes hacia los recitales.",
  "sim.trade-tycoon.title": "Tiburón de oficios",
  "sim.trade-tycoon.desc": "Construye un imperio comercial: compra barato, vende caro, y gestiona el inventario y el flujo de caja en varios mercados.",
  "sim.vehicle-diagnostics.title": "Simulador de diagnóstico y reparación del vehículo",
